insert into dastak_v1.subcategories(category_id,name,slug,status,sort_order,created_by)
select c.id,s.name,s.slug,'DRAFT',s.sort_order,a.account_id
from seed s join dastak_v1.categories c on c.slug=s.category_slug cross join actor a
on conflict(category_id,slug) do update set
 name=excluded.name,sort_order=excluded.sort_order,updated_at=now(),version=dastak_v1.subcategories.version+1;;
